library(ggplot2);library(dplyr);library(sf);library(systemfonts)
register_font('Manrope',plain='assets/Manrope-Regular.ttf',bold='assets/Manrope-Bold.ttf')
cols<-c('Forest'='#00ACA9','Mosaic transition'='#F07F3C','Savanna'='#5E4F9C')
base<-theme_minimal(base_family='Manrope',base_size=22)+theme(plot.background=element_rect(fill='#FAFAFA',colour=NA),panel.grid.minor=element_blank(),panel.grid.major=element_line(colour='#E2E6E8',linewidth=.3),axis.text=element_text(colour='#58595B',size=18),axis.title=element_text(size=20),plot.margin=margin(10,20,10,10),legend.position='none',strip.text=element_text(size=24,face='bold'))
export<-function(p,n,w=12,h=4.6){for(e in c('svg','png','pdf'))ggsave(paste0('assets/',n,'.',e),p,width=w,height=h,device=if(e=='svg')svglite::svglite else if(e=='pdf')cairo_pdf else 'png',dpi=300,bg='#FAFAFA')}
s<-read.csv('seasonality-values.csv');s$eco_zone<-factor(s$eco_zone,levels=names(cols));stopifnot(sum(s$n)==7513)
p<-ggplot(s,aes(calendar_month,p,colour=eco_zone))+geom_line(linewidth=1.2)+geom_point(size=3)+facet_wrap(~eco_zone,nrow=1)+scale_colour_manual(values=cols)+scale_x_continuous(breaks=c(1,3,5,7,9,11),labels=month.abb[c(1,3,5,7,9,11)])+scale_y_continuous(limits=c(0,.6),breaks=seq(0,.6,.2),labels=scales::label_percent())+labs(x=NULL,y='Site-months with flies (%)')+base+theme(panel.grid.major.x=element_blank())
export(p,'closing-season')
g<-read.csv('../seasonality_adapative_sampling/cohort_audit/corrected664/appendixV2_seasonal_summary_table.csv')%>%filter(k==3);g$zone<-factor(g$zone,levels=rev(names(cols)))
p<-ggplot(g,aes(mean,zone,colour=zone))+geom_vline(xintercept=0,colour='#858688',linewidth=.45)+geom_segment(aes(x=min,xend=max,yend=zone),linewidth=2)+geom_point(size=5)+geom_text(aes(label=paste0('+',round(mean),'%')),nudge_y=.24,family='Manrope',size=6.5,colour='#1B1B1B')+scale_colour_manual(values=cols)+scale_x_continuous(limits=c(0,310),breaks=c(0,100,200,300),labels=function(x)paste0(x,'%'))+labs(x='Expected gain in remaining catch: replace versus continue',y=NULL)+base+theme(axis.text.y=element_text(size=22,colour='#1B1B1B'),panel.grid.major.y=element_blank())
export(p,'closing-gain')
a<-readRDS('../outputs/sampling_app_cache/Abia.rds');r<-read.csv('../outputs/ranked_reserve_sites/abia_primary_and_ranked_reserves.csv');r<-r%>%filter(site_role=='Primary'|site_rank<=30);rp<-st_as_sf(r,coords=c('longitude','latitude'),crs=4326);gs<-st_as_sf(a$grid,coords=c('longitude','latitude'),crs=4326)
p<-ggplot()+geom_sf(data=gs,aes(colour=p_presence),shape=15,size=.7,stroke=0)+scale_colour_gradientn(colours=c('#EEF5FA','#C7DEEF','#92BDDD','#4E96C8','#0057BF'),limits=c(0,1),breaks=c(0,.5,1),labels=scales::label_percent(),name='Probability of finding flies',guide=guide_colourbar(direction='horizontal',title.position='top',barwidth=grid::unit(8,'cm'),barheight=grid::unit(.3,'cm')))+geom_sf(data=a$state_ll,fill=NA,colour='#58595B',linewidth=.5)+geom_sf(data=rp[rp$site_role=='Primary',],shape=21,fill='#F07F3C',colour='#FAFAFA',size=3,stroke=.65)+geom_sf(data=rp[rp$site_role!='Primary',],shape=21,fill='#FAFAFA',colour='#1B1B1B',size=2.6,stroke=.7)+theme_void(base_family='Manrope',base_size=19)+theme(plot.background=element_rect(fill='#FAFAFA',colour=NA),legend.position='top',legend.title=element_text(size=17),legend.text=element_text(size=16))
export(p,'closing-reserves',7,7)
c<-read.csv('data/presence-calibration-isotonic-curve.csv');b<-read.csv('data/presence-calibration-consistency-band.csv')
v<-data.frame(x=c$x_max[-nrow(c)],y=c$CEP_pav[-nrow(c)],yend=c$CEP_pav[-1])
p<-ggplot()+geom_ribbon(data=b,aes(x=x,ymin=lower,ymax=upper),fill='#C7DEEF',alpha=.8)+geom_abline(slope=1,intercept=0,colour='#58595B',linetype=2,linewidth=.7)+geom_segment(data=c,aes(x=x_min,xend=x_max,y=CEP_pav,yend=CEP_pav),colour='#C20019',linewidth=1.2)+geom_segment(data=v,aes(x=x,xend=x,y=y,yend=yend),colour='#C20019',linewidth=1.2)+scale_x_continuous(limits=c(0,1),breaks=c(0,.25,.5,.75,1),labels=scales::label_percent())+scale_y_continuous(limits=c(0,1),breaks=c(0,.25,.5,.75,1),labels=scales::label_percent())+labs(x='Predicted probability',y='Observed proportion with flies')+base+coord_fixed()
export(p,'closing-calibration',7.5,6.2)
system2('python3','embed_svg_fonts.py')
